Here's a C++ function that converts markdown formatted text to HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string &markdown) {
    std::string html;
    std::istringstream stream(markdown);
    std::string line;

    while (std::getline(stream, line)) {
        // Convert text to HTML for each line
        html += "<p>" + line + "</p>";
    }

    return html;
}

int main() {
    std::string markdown = "This is a markdown paragraph.\nThis is a second paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << "Markdown: " << markdown << std::endl;
    std::cout << "HTML: " << html << std::endl;
    return 0;
}
```

